import{_ as n,o as t,c as a,a2 as s}from"./chunks/framework.CYj0tiXz.js";const h=JSON.parse('{"title":"Changelog","description":"BlendSDK release notes and version history","frontmatter":{"title":"Changelog","description":"BlendSDK release notes and version history"},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1791067132000}'),r={name:"reference/changelog.md"};function o(i,e,l,d,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="blendsdk-v5-66-0-—-release-notes" tabindex="-1">BlendSDK v5.66.0 — Release Notes <a class="header-anchor" href="#blendsdk-v5-66-0-—-release-notes" aria-label="Permalink to &quot;BlendSDK v5.66.0 — Release Notes&quot;">​</a></h1><p><strong>Released</strong>: 2026-10-01</p><p>We are excited to announce the release of BlendSDK version 5.66.0. This update brings a range of improvements and refinements to enhance the overall user experience and ensure better performance across several packages. Our goal with this release is to deliver a more secure, reliable, and user-friendly experience, making it easier for teams to integrate and utilize the SDK effectively.</p><p><strong>Key Highlights:</strong></p><p><strong>1. Enhanced Security Measures</strong><br> This release includes significant updates to the authentication processes, improving security for user sessions and data. New mechanisms have been added to protect against unauthorized access and to reinforce our commitment to safeguarding user information.</p><p><strong>2. Improved Documentation</strong><br> We&#39;ve dedicated time to enhance our documentation, ensuring users have clear, concise, and updated information readily available. This includes better examples and guides, which will help users navigate and implement the SDK more easily.</p><p><strong>3. Performance Optimizations</strong><br> Various internal improvements have been made to increase the efficiency of the SDK. These changes are designed to improve response times and resource utilization, resulting in a smoother experience for users.</p><p><strong>4. New Features and Enhancements</strong><br> New functionalities have been implemented across several packages, which enable users to leverage advanced capabilities without complication. This includes enhancements in the authorization workflows and support for more integration options.</p><p><strong>5. Bug Fixes and Stability Improvements</strong><br> We have addressed several bugs reported by users, leading to a more stable and reliable SDK. These fixes will help users minimize disruptions and focus on their core tasks.</p><p>Overall, BlendSDK version 5.66.0 is a step forward in our ongoing effort to provide a robust and user-centric software development kit. We encourage stakeholders to take advantage of these improvements to drive better outcomes in their projects. Thank you for your continued support!</p><hr><p><em>Install: <code>npm install blendsdk@5</code></em><em>Full changelog: See individual package CHANGELOG.md files</em></p>',12)])])}const m=n(r,[["render",o]]);export{h as __pageData,m as default};
